import type { IdentityConfigMeta } from "./types.js";

function readCookie(name: string): string | null {
  if (typeof document === "undefined") return null;
  const match = document.cookie.match(new RegExp(`(?:^|; )${name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}=([^;]*)`));
  return match ? decodeURIComponent(match[1]) : null;
}

function getByPath(root: unknown, path: string): unknown {
  const parts = path.split(".").filter(Boolean);
  let cur: unknown = root;
  for (const part of parts) {
    if (cur == null || typeof cur !== "object") return undefined;
    cur = (cur as Record<string, unknown>)[part];
  }
  return cur;
}

const ANON_KEY = "ziffsplit_anon_id";

function ensureAnonId(): string {
  if (typeof localStorage === "undefined") {
    return `anon_${Math.random().toString(36).slice(2)}`;
  }
  let id = localStorage.getItem(ANON_KEY);
  if (!id) {
    id = `anon_${crypto.randomUUID?.() ?? Math.random().toString(36).slice(2)}`;
    localStorage.setItem(ANON_KEY, id);
  }
  return id;
}

/**
 * Resolve a stable user/anon id for bucketing.
 * Prefer getUserId hook, then declarative identity, then SDK-managed anon id.
 */
export function resolveStableId(options: {
  getUserId?: () => string | null;
  identity?: IdentityConfigMeta | null;
}): { userId?: string; anonId?: string; stableId: string } {
  if (options.getUserId) {
    const userId = options.getUserId();
    if (userId) return { userId, stableId: userId };
  }

  const identity = options.identity;
  if (identity) {
    const cfg = identity.config ?? {};
    if (identity.strategy === "cookie") {
      const name = String(cfg.cookieName ?? "ab_user_id");
      const value = readCookie(name);
      if (value) return { userId: value, stableId: value };
    }
    if (identity.strategy === "localStorage") {
      const key = String(cfg.key ?? "ab_user_id");
      const value = typeof localStorage !== "undefined" ? localStorage.getItem(key) : null;
      if (value) return { userId: value, stableId: value };
    }
    if (identity.strategy === "globalVar") {
      const path = String(cfg.path ?? "window.__USER_ID__");
      const cleaned = path.replace(/^window\./, "");
      const value = getByPath(typeof window !== "undefined" ? window : {}, cleaned);
      if (typeof value === "string" && value) return { userId: value, stableId: value };
    }
  }

  const anonId = ensureAnonId();
  return { anonId, stableId: anonId };
}
