import { bucketVariant, inRollout } from "./bucketing.js";
import { resolveStableId } from "./identity.js";
import {
  dispatchPreviewChange,
  isPreviewMode,
  parsePreviewMessage,
  readPreviewFromUrl,
  type PreviewOverride,
} from "./preview.js";
import {
  clearDebugSalt,
  clearStoredAssignment,
  clearStoredAssignments,
  getDebugSalt,
  getStoredAssignment,
  listStoredAssignments,
  pruneAssignments,
  setDebugSalt,
  setStoredAssignment,
} from "./storage.js";
import { evaluateRules } from "./targeting.js";
import type {
  AbSdk,
  Assignment,
  ConfigPayload,
  ExperimentConfig,
  ExposureEvent,
  InitOptions,
} from "./types.js";

const DEFAULT_API_BASE = "";
const DEFAULT_POLL_MS = 60_000;

export function init(options: InitOptions): AbSdk {
  const apiBaseUrl = options.apiBaseUrl ?? DEFAULT_API_BASE;
  let config: ConfigPayload | null = null;
  const exposureCallbacks: Array<(event: ExposureEvent) => void> = [];
  const exposedThisSession = new Set<string>();
  let pollTimer: ReturnType<typeof setInterval> | null = null;
  let previewOverride: PreviewOverride | null = null;
  let previewMessageHandler: ((event: MessageEvent) => void) | null = null;

  function applyPreviewOverride(next: PreviewOverride | null) {
    if (!isPreviewMode()) {
      previewOverride = null;
      return;
    }
    previewOverride = next;
    dispatchPreviewChange(next);
  }

  function syncPreviewFromLocation() {
    applyPreviewOverride(readPreviewFromUrl());
  }

  if (typeof window !== "undefined") {
    syncPreviewFromLocation();
    previewMessageHandler = (event: MessageEvent) => {
      if (!isPreviewMode()) return;
      const parsed = parsePreviewMessage(event.data);
      if (!parsed) return;
      applyPreviewOverride(parsed);
    };
    window.addEventListener("message", previewMessageHandler);
    window.addEventListener("hashchange", syncPreviewFromLocation);
  }

  async function fetchConfig(): Promise<ConfigPayload> {
    const url = `${apiBaseUrl}/v1/config/${encodeURIComponent(options.siteKey)}`;
    const res = await fetch(url, { cache: "no-store" });
    if (!res.ok) {
      throw new Error(`Failed to fetch config: ${res.status}`);
    }
    return res.json() as Promise<ConfigPayload>;
  }

  function applyConfig(next: ConfigPayload) {
    config = next;
    pruneAssignments(
      next.experiments.map((e) => ({
        key: e.key,
        variantKeys: e.variants.map((v) => v.key),
      })),
    );
  }

  function identityForResolve() {
    return options.identity ?? config?.identity ?? null;
  }

  function attributes(): Record<string, unknown> {
    const pathname =
      typeof globalThis !== "undefined" && "location" in globalThis
        ? String((globalThis as { location?: { pathname?: string } }).location?.pathname ?? "")
        : "";
    return {
      urlPath: pathname,
      ...(options.attributes ?? {}),
    };
  }

  function findExperiment(experimentKey: string): ExperimentConfig | undefined {
    return config?.experiments.find((e) => e.key === experimentKey);
  }

  function fireExposure(assignment: Assignment, ids: ReturnType<typeof resolveStableId>) {
    // Preview traffic should not pollute exposure streams.
    if (previewOverride && previewOverride.experimentKey === assignment.experimentKey) {
      return;
    }
    if (exposedThisSession.has(assignment.experimentKey)) return;
    exposedThisSession.add(assignment.experimentKey);

    const event: ExposureEvent = {
      experimentKey: assignment.experimentKey,
      variantKey: assignment.variantKey,
      containerKey: assignment.containerKey,
      userId: ids.userId,
      anonId: ids.anonId,
      timestamp: new Date().toISOString(),
      deliveryMode: assignment.deliveryMode,
      contentSource: assignment.contentSource,
      primaryKpi: assignment.primaryKpi,
      siteKey: options.siteKey,
      configVersion: config?.version ?? 0,
    };

    for (const cb of exposureCallbacks) {
      try {
        cb(event);
      } catch {
        // Host callback errors must not break evaluation
      }
    }
  }

  function evaluateAssignment(experimentKey: string): Assignment | null {
    const experiment = findExperiment(experimentKey);
    if (!experiment || !config) return null;

    const ids = resolveStableId({
      getUserId: options.getUserId,
      identity: identityForResolve(),
    });

    const forced =
      previewOverride && previewOverride.experimentKey === experimentKey
        ? previewOverride
        : null;

    let variantKey = forced?.variantKey ?? getStoredAssignment(experimentKey);

    // Stale sticky (or stale force without draft content) after a variant rename
    // / replace — clear and fall through to normal bucketing.
    if (
      variantKey &&
      !experiment.variants.some((v) => v.key === variantKey) &&
      !(forced && forced.authoredContent !== undefined)
    ) {
      if (!forced) {
        clearStoredAssignment(experimentKey);
      }
      variantKey = null;
    }

    if (!variantKey) {
      if (!evaluateRules(experiment.targetingRules, attributes())) return null;
      if (!inRollout(ids.stableId, experimentKey, experiment.rolloutPercent)) return null;

      const debugSalt = getDebugSalt();
      const bucketExperimentKey = debugSalt
        ? `${experimentKey}:debug:${debugSalt}`
        : experimentKey;
      variantKey = bucketVariant(ids.stableId, bucketExperimentKey, experiment.variants);
      if (!variantKey) return null;
      if (!forced) {
        setStoredAssignment(experimentKey, variantKey);
      }
    }

    const variant = experiment.variants.find((v) => v.key === variantKey);
    if (!variant) {
      // Allow admin live-preview of a draft / newly renamed variant that is not
      // in the published config yet, as long as authored content was provided.
      if (forced && forced.authoredContent !== undefined) {
        return {
          experimentKey,
          variantKey: forced.variantKey,
          containerKey: experiment.containerKey,
          deliveryMode: experiment.deliveryMode,
          contentSource: "authored",
          authoredContent: forced.authoredContent,
          primaryKpi: experiment.primaryKpi,
        };
      }
      return null;
    }

    const assignment: Assignment = {
      experimentKey,
      variantKey: variant.key,
      variantDisplayName: variant.displayName,
      containerKey: experiment.containerKey,
      deliveryMode: experiment.deliveryMode,
      contentSource:
        forced?.authoredContent !== undefined ? "authored" : variant.contentSource,
      authoredContent:
        forced?.authoredContent !== undefined
          ? forced.authoredContent
          : variant.authoredContent,
      codeVariantKey: variant.codeVariantKey,
      primaryKpi: experiment.primaryKpi,
    };

    fireExposure(assignment, ids);
    return assignment;
  }

  const sdk: AbSdk = {
    siteKey: options.siteKey,
    get config() {
      return config;
    },
    async init() {
      applyConfig(await fetchConfig());

      const pollMs = options.pollIntervalMs ?? DEFAULT_POLL_MS;
      if (pollMs > 0 && typeof setInterval !== "undefined") {
        pollTimer = setInterval(() => {
          fetchConfig()
            .then(applyConfig)
            .catch(() => {
              // Keep last good config on poll failure
            });
        }, pollMs);
      }
    },
    getAssignment(experimentKey: string): Assignment | null {
      return evaluateAssignment(experimentKey);
    },
    getContent(experimentKey: string): string | null {
      const assignment = evaluateAssignment(experimentKey);
      if (!assignment) return null;
      if (assignment.contentSource === "authored") {
        return assignment.authoredContent ?? null;
      }
      return null;
    },
    getAssignmentByContainer(containerKey: string): Assignment | null {
      if (!config) return null;

      // Admin live-preview forces a specific experiment; use it when that
      // experiment is registered on this container.
      if (previewOverride) {
        const forcedExp = findExperiment(previewOverride.experimentKey);
        if (forcedExp?.containerKey === containerKey) {
          return evaluateAssignment(previewOverride.experimentKey);
        }
      }

      const experiments = config.experiments.filter(
        (e) => e.containerKey === containerKey,
      );
      for (const experiment of experiments) {
        const assignment = evaluateAssignment(experiment.key);
        if (assignment) return assignment;
      }
      return null;
    },
    getContentByContainer(containerKey: string): string | null {
      const assignment = sdk.getAssignmentByContainer(containerKey);
      if (!assignment) return null;
      if (assignment.contentSource === "authored") {
        return assignment.authoredContent ?? null;
      }
      return null;
    },
    getAssignments() {
      if (!config) return [];
      const out: Assignment[] = [];
      for (const experiment of config.experiments) {
        const assignment = evaluateAssignment(experiment.key);
        if (assignment) out.push(assignment);
      }
      return out;
    },
    listAssignments() {
      return listStoredAssignments();
    },
    clearAssignments(options?: { rebucket?: boolean }) {
      clearStoredAssignments();
      exposedThisSession.clear();
      if (options?.rebucket) {
        const salt =
          typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
            ? crypto.randomUUID()
            : `dbg_${Math.random().toString(36).slice(2)}`;
        setDebugSalt(salt);
      } else {
        clearDebugSalt();
      }
    },
    setPreviewOverride(override) {
      applyPreviewOverride(override);
    },
    onExposure(callback: (event: ExposureEvent) => void) {
      exposureCallbacks.push(callback);
    },
    destroy() {
      if (pollTimer) {
        clearInterval(pollTimer);
        pollTimer = null;
      }
      if (typeof window !== "undefined") {
        if (previewMessageHandler) {
          window.removeEventListener("message", previewMessageHandler);
          previewMessageHandler = null;
        }
        window.removeEventListener("hashchange", syncPreviewFromLocation);
      }
      previewOverride = null;
    },
  };

  return sdk;
}

export type {
  AbSdk,
  Assignment,
  ConfigPayload,
  ExposureEvent,
  ExperimentConfig,
  InitOptions,
} from "./types.js";

export {
  buildPreviewUrl,
  encodePreviewHash,
  PREVIEW_CHANGE_EVENT,
  PREVIEW_MESSAGE_TYPE,
  postPreviewOverride,
} from "./preview.js";
