const STORAGE_KEY = "ziffsplit_assignments";
const DEBUG_SALT_KEY = "ziffsplit_debug_salt";

type AssignmentMap = Record<string, string>;

function readAll(): AssignmentMap {
  if (typeof localStorage === "undefined") return {};
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== "object") return {};
    return parsed as AssignmentMap;
  } catch {
    return {};
  }
}

function writeAll(map: AssignmentMap): void {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(map));
  } catch {
    // Ignore quota / private mode failures — assignment still works in-memory for the session.
  }
}

export function getStoredAssignment(experimentKey: string): string | null {
  return readAll()[experimentKey] ?? null;
}

export function setStoredAssignment(experimentKey: string, variantKey: string): void {
  const map = readAll();
  map[experimentKey] = variantKey;
  writeAll(map);
}

export function clearStoredAssignment(experimentKey: string): void {
  const map = readAll();
  if (!(experimentKey in map)) return;
  delete map[experimentKey];
  writeAll(map);
}

export function listStoredAssignments(): Array<{ experimentKey: string; variantKey: string }> {
  return Object.entries(readAll()).map(([experimentKey, variantKey]) => ({
    experimentKey,
    variantKey,
  }));
}

/** Remove all sticky experiment → variant assignments from localStorage. */
export function clearStoredAssignments(): void {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {
    // ignore
  }
}

/** Debug-only salt mixed into bucketing so testers can land in a new arm. */
export function getDebugSalt(): string | null {
  if (typeof localStorage === "undefined") return null;
  try {
    return localStorage.getItem(DEBUG_SALT_KEY);
  } catch {
    return null;
  }
}

export function setDebugSalt(salt: string): void {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(DEBUG_SALT_KEY, salt);
  } catch {
    // ignore
  }
}

export function clearDebugSalt(): void {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.removeItem(DEBUG_SALT_KEY);
  } catch {
    // ignore
  }
}

/** Drop assignments for experiments no longer present, or variants removed. */
export function pruneAssignments(
  liveExperiments: Array<{ key: string; variantKeys: string[] }>,
): void {
  const live = new Map(liveExperiments.map((e) => [e.key, new Set(e.variantKeys)]));
  const map = readAll();
  let changed = false;
  for (const key of Object.keys(map)) {
    const variants = live.get(key);
    if (!variants) {
      delete map[key];
      changed = true;
      continue;
    }
    if (!variants.has(map[key]!)) {
      delete map[key];
      changed = true;
    }
  }
  if (changed) writeAll(map);
}
